@Override public void removeLast() {
  stateCount++;
  Object item = lastItem;
  try {
    map.get(lastItem).unlinkSelf();
    map.remove(item);
  } catch (ClassCastException e) {
    // 处理类型转换错误
    throw new RuntimeException("Invalid item type for map", e);
  } catch (NullPointerException e) {
    // 处理null值错误
    throw new RuntimeException("Null item not allowed in map", e);
  }
}
